def OffLineOrNonSimple (s : ℂ) : Prop :=
  completedRiemannZeta₀ s = 0 ∧ 0 < s.re ∧ s.re < 1 ∧
  (s.re ≠ 1 / 2 ∨ deriv completedRiemannZeta₀ s = 0)

def C1 : MechanismClass ℂ OffLineOrNonSimple :=
  { name := "Balance"
    produces := fun s => s.re ≠ 1 / 2 }

def C2 : MechanismClass ℂ OffLineOrNonSimple :=
  { name := "Conjugation"
    produces := fun s => s.re ≠ 1 / 2 }

def C_simple : MechanismClass ℂ OffLineOrNonSimple :=
  { name := "Simplicity"
    produces := fun s => s.re = 1 / 2 ∧ deriv completedRiemannZeta₀ s = 0 }

def RHHypothesis : Prop :=
  ∀ (s : ℂ), completedRiemannZeta₀ s = 0 →
  0 < s.re → s.re < 1 → s.re = 1 / 2

def SimplicityHypothesis : Prop :=
  ∀ (s : ℂ), completedRiemannZeta₀ s = 0 →
  s.re = 1 / 2 → deriv completedRiemannZeta₀ s ≠ 0

def zeroSide (k : ℝ → ℂ) : ℂ :=
  ∑' ρ : Zeta23.zetaZeroConfig.carrier,
    (Zeta23.zetaZeroConfig.mult ρ : ℂ) * Zeta23.paperFT k (Zeta23.gammaOf ρ)

def conservationHypothesis : Prop :=
  ∀ σ : ℝ, (∃ t : ℝ, riemannZeta (⟨σ, t⟩ : ℂ) = 0 ∧ ¬ (∃ n : ℕ, (⟨σ, t⟩ : ℂ) = -2 * ((n : ℂ) + 1)) ∧ (⟨σ, t⟩ : ℂ) ≠ 1) →
    ∃ p : ℕ, ∃ _ : Nat.Prime p, (p : ℝ) ^ (-σ) = (p : ℝ) ^ (-(1 - σ))

def zeroSideNeg : Prop :=
  ∀ (g0 : ℝ → ℝ) (L M : ℝ), PWSetup Zeta23.zetaZeroConfig g0 L M → ∀ ρs ∈ tieSet Zeta23.zetaZeroConfig g0 M,
    ∃ (a : List ℝ) (j : ℕ), (zeroSide (kWindow a g0 j)).re < 0

def liCoeff (n : ℕ) : ℝ :=
  ∑' ρ : {ρ : ℂ // ρ ∈ Zeta23.zetaZeroConfig.carrier ∧ 0 < ρ.im},
    (Zeta23.zetaZeroConfig.mult ρ : ℝ) * (2 * (1 - (1 - 1 / (ρ : ℂ)) ^ n).re)

theorem completedZeta_ne_zero_on_horizontals {c : ℝ} (hc1 : 1 < c) (hc2 : c ≤ 3 / 2) {R : ℝ}
    (hζ : ∀ s : ℂ, (s.im = R ∨ s.im = -R) → 1 / 2 ≤ s.re → s.re ≤ 2 → riemannZeta s ≠ 0) :
    ∀ s : ℂ, (s.im = R ∨ s.im = -R) → 1 - c ≤ s.re → s.re ≤ c → completedRiemannZeta s ≠ 0 :=
